INSERT IGNORE INTO `products` (`id`,`title`,`slug`,`description`,`price`,`sale_price`,`category`,`condition`,`sku`,`stock_quantity`,`status`,`featured`,`images`,`primary_image`,`created_date`,`updated_date`) VALUES ('product_1790244486745_cwpd','DS6878 Series Scanner','ds6878-series-scanner','The Zebra DS6878-SR cordless imager offers the complete data capture functionality required to streamline and error-proof everyday processes in a wide variety of industries. This single device can capture all common bar codes (1-D, 2-D and PDF417) on labels as well as on mobile phone displays. The optional hands-free presentation cradle enables additional advanced capabilities, including: the ability to capture signatures, documents and photographs; optical character recognition (OCR) to capture the text in documents; and MICR to capture the numeric information on the bottom of checks. Electronic record keeping is enriched and checks can be instantly converted to electronic debit transactions, reducing the time and cost associated with processing paper checks as well as the risk of check fraud. Add easy remote management, business-class durability, future proofing and world-class support and you have a scanner that not only offers the advanced data capture features your users need, but also the extraordinary total cost of ownership (TCO) required to easily justify this technology investment.

','0',NULL,'scanners','new','',100,'active',0,'["https://www.zebra.com/content/dam/support-dam/global/photography/web-production/0001/ds6878-photography-website.jpg.imgo.jpg","https://www.barcode-arena.com/media/catalog/product/cache/9a2bd0630056ce431ee3b3a11cf432b9/d/s/ds6878_black_1_1.jpg","https://www.zebra.com/content/dam/support-dam/global/photography/web-production/0001/ds6878-photography-website.jpg"]','https://www.zebra.com/content/dam/support-dam/global/photography/web-production/0001/ds6878-photography-website.jpg.imgo.jpg','2026-09-24 15:08:06','2026-09-24 15:08:06');
